function [power_signals, current_signals, pll_signals] = mfun_gfl_monitored_signals(fbk_in, ref_in, p)
%MFUN_GFL_MONITORED_SIGNALS Block Monitored signals of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN).
fbk = gfl_feedbacks_unpack(fbk_in);
ref = gfl_references_unpack(ref_in);
% Monitored signals
power_signals = [ref.p_g; fbk.p_g; ref.q_g; fbk.q_g];
current_signals = [real(ref.i_c); real(fbk.i_c); imag(ref.i_c); imag(fbk.i_c)];
pll_signals = [fbk.u_g; fbk.w_g; fbk.theta_c];
end

function s = gfl_feedbacks_unpack(u)
%GFL_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_g', u(5), ...
    'u_g_meas', complex(u(6), u(7)), ...
    'theta_c', u(8), ...
    'w_g', u(9), ...
    'w_c', u(10), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'eps', u(13));
end

function s = gfl_references_unpack(u)
%GFL_REFERENCES_UNPACK Struct of the signal vector u.
s = struct( ...
    'p_g', u(1), ...
    'q_g', u(2), ...
    'i_c', complex(u(3), u(4)), ...
    'u_c', complex(u(5), u(6)));
end
